library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all;
entity soqpsk_timing_ted is generic(SPS:positive:=8); port(clk,reset,valid:in std_logic; i_in,q_in:in signed(31 downto 0); symbol_tick:out std_logic; error:out signed(31 downto 0)); end;
architecture rtl of soqpsk_timing_ted is signal count:natural range 0 to SPS-1:=0; signal pi,pq:signed(31 downto 0):=(others=>'0'); begin process(clk) variable e:signed(31 downto 0); variable p0,p1:signed(63 downto 0); begin if rising_edge(clk) then symbol_tick<='0'; if reset='1' then count<=0;pi<=(others=>'0');pq<=(others=>'0');error<=(others=>'0'); elsif valid='1' then p0:=pi*i_in; p1:=pq*q_in; e:=resize(shift_right(p0+p1,8),32); error<=e; pi<=i_in;pq<=q_in; if count=SPS-1 then count<=0;symbol_tick<='1';else count<=count+1;end if; end if; end if; end process; end;
